private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Handle null or impossible rotation
    if (node == null || node.left == null) {
        return node;
    }

    TreeNode<T> leftChild = node.left;
    TreeNode<T> rightOfLeft = leftChild.right;

    // Perform rotation
    leftChild.right = node;
    node.left = rightOfLeft;

    // Update parent references if they exist
    TreeNode<T> oldParent = node.parent;
    leftChild.parent = oldParent;
    node.parent = leftChild;

    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    // Reconnect with the old parent
    if (oldParent != null) {
        if (oldParent.left == node) {
            oldParent.left = leftChild;
        } else if (oldParent.right == node) {
            oldParent.right = leftChild;
        }
    }

    return leftChild;
