void insertBefore(Bucket bucket){
    // Validate input
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    // If this is already immediately before the target bucket, nothing to do
    if (this.next == bucket || bucket.prev == this) {
        return;
    }

    // Detach this bucket from its current position, if any
    Bucket oldPrev = this.prev;
    Bucket oldNext = this.next;
    if (oldPrev != null) {
        oldPrev.next = oldNext;
    }
    if (oldNext != null) {
        oldNext.prev = oldPrev;
    }

    // Insert this bucket before the target bucket
    Bucket targetPrev = bucket.prev; // may be null
    this.prev = targetPrev;
    this.next = bucket;

    if (targetPrev != null) {
        targetPrev.next = this;
    }
    bucket.prev = this;
