public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str is null");
    }
    if (len < 0) {
        throw new IndexOutOfBoundsException("len is negative: " + len);
    }
    if (index < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException(
                "index out of bounds: index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    if (len == 0) {
        return 0;
    }

    int size = 0;
    final int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Valid surrogate pair -> 4 bytes
            size += 4;
            i++; // Skip low surrogate
        } else {
            // Either a low surrogate without a preceding high surrogate,
            // or a non-surrogate character in the U+0800..U+FFFF range
            size += 3;
        }
    }
    return size;
