private boolean unlink(ListNodeImpl<E> node) {
    // Guard against null input
    if (node == null) {
        return false;
    }

    // Verify that the node is actually part of this list.
    // If the node is not linked correctly, we consider it not part of the list.
    if (node.prev != null && node.prev.next != node) {
        return false;
    }
    if (node.next != null && node.next.prev != node) {
        return false;
    }

    // Remove the node from the list
    if (node.prev == null) { // node is head
        head = node.next;
        if (head != null) {
            head.prev = null;
        } else {
            // List becomes empty
            tail = null;
        }
    } else {
        node.prev.next = node.next;
    }

    if (node.next == null) { // node is tail
        tail = node.prev;
        if (tail != null) {
            tail.next = null;
        } else {
            // List becomes empty
            head = null;
        }
    } else {
        node.next.prev = node.prev;
    }

    // Help garbage collection
    node.next = null;
    node.prev = null;

    // Update size
    size--;

    return true;
