private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long totalSum = 0L;
    long running = 0L;

    // Compute total sum and suffix sums in one pass from the end
    for (int i = n - 1; i >= 0; i--) {
        int value = bounds.get(i);
        totalSum += value;
        running += value;
        // Insert at the beginning to maintain original order
        suffix.add(0, (int) running);
    }

    return new Pair<>(suffix, totalSum);
}<|return|>

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int length = arr.length;
    if (from < 0 || to < 0 || from >= length || to >= length) {
        throw new IllegalArgumentException("Indices out of bounds: from=" + from + ", to=" + to + ", length=" + length);
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index: from=" + from + ", to=" + to);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
