private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A null or empty set is trivially a clique
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }

    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);

    // Check that all vertices are present in the graph
    for (V v : vertexList) {
        if (v == null || !graph.containsVertex(v)) {
            return false;
        }
    }

    // For each unordered pair of distinct vertices, check for an edge
    for (int i = 0; i < vertexList.size(); i++) {
        V u = vertexList.get(i);
        for (int j = i + 1; j < vertexList.size(); j++) {
            V w = vertexList.get(j);
            // For undirected graphs, containsEdge(u, w) is sufficient.
            // For directed graphs, we consider a clique if there is an edge in either direction.
            if (!graph.containsEdge(u, w) && !graph.containsEdge(w, u)) {
                return false;
            }
        }
    }
    return true;
}<|return|>

