            if (shift == 0) {
                return 0;
            }
            // If EOF occurs mid-varint, it's an error.
            throw new IOException("Truncated varint while reading tag");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    // If we get here, the varint was too long (more than 5 bytes for a 32‑bit value).
    throw new IOException("Varint too long while reading tag");
